package cn.cccs7.cynexus.market.infra.portfolio;
import cn.cccs7.cynexus.market.domain.portfolio.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class PortfolioTradePlanRepositoryAdapter implements PortfolioTradePlanRepository { private final JdbcTemplate jdbc; private final PortfolioIdGenerator ids; public PortfolioTradePlanRepositoryAdapter(JdbcTemplate j,PortfolioIdGenerator i){jdbc=j;ids=i;}
 public List<PortfolioTradePlanBO> list(String p,String t,String symbol){return jdbc.query("select plan_id,symbol,instrument_type,strategy,thesis,planned_entry_price,stop_loss_price,target_price,planned_position_pct,risk_amount,expected_holding_days,confidence_score,market_regime,created_at from cynexus_appl_market.portfolio_trade_plan where principal_key=? and tenant_key=? and (? is null or symbol=?) order by created_at desc",(r,n)->new PortfolioTradePlanBO(r.getLong(1),r.getString(2),PortfolioInstrumentType.fromPayload(r.getString(3)),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getObject(11,Integer.class),r.getBigDecimal(12),r.getString(13),r.getObject(14,java.time.OffsetDateTime.class)),p,t,symbol,symbol);}
 public PortfolioTradePlanBO save(String p,String t,PortfolioTradePlanBO x){long id=ids.nextId(); jdbc.update("insert into cynexus_appl_market.portfolio_trade_plan(plan_id,principal_key,tenant_key,symbol,instrument_type,strategy,thesis,planned_entry_price,stop_loss_price,target_price,planned_position_pct,risk_amount,expected_holding_days,confidence_score,market_regime,created_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,p,t,x.symbol(),x.instrumentType().name(),x.strategy(),x.thesis(),x.plannedEntryPrice(),x.stopLossPrice(),x.targetPrice(),x.plannedPositionPct(),x.riskAmount(),x.expectedHoldingDays(),x.confidenceScore(),x.marketRegime(),x.createdAt()); return new PortfolioTradePlanBO(id,x.symbol(),x.instrumentType(),x.strategy(),x.thesis(),x.plannedEntryPrice(),x.stopLossPrice(),x.targetPrice(),x.plannedPositionPct(),x.riskAmount(),x.expectedHoldingDays(),x.confidenceScore(),x.marketRegime(),x.createdAt()); }
}
